      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-air-alliance",
        { "text", text = "|cOXP_ENEMY_Charlga Razorflank|r" },
        { "text", text = "Razorfen Kraul is a five-player dungeon at the southern edge of the Barrens (the arrow points at its entrance); |cOXP_ENEMY_Charlga Razorflank|r (level 33 elite) is its last boss. She casts Chain Bolt, Renew on her allies and Purity; the |cOXP_LOOT_Tattered Note|r drops only from her." },
        { "goto", x = 42.9, y = 90.2, zone = "1413" },
