      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-air-alliance",
        { "text", text = "The steam pools" },
        { "text", text = "|cOXP_FRIENDLY_Veyric Thunderhame|r hands you the |cOXP_LOOT_Corrupted Totems|r. Thousand Needles is far: the boat to Theramore and the road west, or fly to Thalanaar on the Feralas border and head east into the canyon. Place the |cOXP_LOOT_Corrupted Totems|r at the steam pools north-west of Freewind Post to call the corrupted elementals and then the |cOXP_ENEMY_Ravaging Tempest|r; Razormane quilboar join the fight while the ritual runs. A group quest: bring at least one or two friends. The |cOXP_LOOT_Eye of the Tempest|r drops about every other kill, and every group member can loot it." },
        { "xp", level = 38, text = "Reach level 38" },
        { "goto", x = 36.72, y = 39.25, zone = "1441" },
        { "complete", obj = 1, quest = 96135, text = "Eye of the Tempest: 1 (|cOXP_LOOT_Eye of the Tempest|r, from the |cOXP_ENEMY_Ravaging Tempest|r)" },
        { "mob", name = "Ravaging Tempest" },
      },
