      { only = "Shaman", source = "polestar:forever/class/shaman/call-of-air-alliance",
        { "text", text = "|cOXP_FRIENDLY_Bath'rah the Windwatcher|r" },
        { "text", text = "|cOXP_FRIENDLY_Bath'rah the Windwatcher|r camps in the ruins in the east of Alterac Mountains: from Tarren Mill follow the river east of town north into the hills. Pick your weapon: |cOXP_LOOT_Lightning's Grasp|r, |cOXP_LOOT_Tidebringer's Claw|r or |cOXP_LOOT_Rage of the Storm|r." },
        { "goto", x = 80.5, y = 66.92, zone = "1416" },
        { "turnin", quest = 96016, text = "Turn in The Tempest's Weapons (|cOXP_FRIENDLY_Bath'rah the Windwatcher|r: the |cOXP_LOOT_Elementalist's Guard|r and your weapon)" },
        { "target", name = "Bath'rah the Windwatcher" },
      },
      { only = "Human Warrior/NightElf Warrior/Skyborne Warrior", source = "polestar:forever/class/warrior/whirlwind-weapon",
        { "text", text = "Class quest: {quest:1792}" },
        { "text", text = "The Islander (Stormwind)" },
        { "text", text = "At 30, |cOXP_FRIENDLY_Wu Shen|r, beside |cOXP_FRIENDLY_Ilsa Corbin|r in the warrior trainers' building of |cOXP_PICK_Old Town|r, sends you to |cOXP_FRIENDLY_Klannoc Macleod|r on Fray Island in the Barrens." },
