        { "text", text = "The demon's spirit" },
        { "text", text = "Back to |cOXP_FRIENDLY_Menara Voidrender|r in the tower above Ratchet with the spirit and the gem first: her orb follows from it." },
        { "goto", x = 62.51, y = 35.45, zone = "1413" },
